        "tr": {
          "auteur": "Diyanet İşleri Başkanlığı",
          "texte": "Ama Peygamber ve onunla beraber bulunan müminler, mallariyle ve canlariyle savaştılar. İşte iyilikler onlaradır, saadete erişenler de onlardır"
        }
